package os.aios.search.probe;
import android.app.Instrumentation;import android.os.*;import android.graphics.*;import java.io.*;import java.nio.*;import java.nio.file.*;import java.util.*;import org.json.*;import os.aios.core.embedding.LiteRtGpuBackend;import os.aios.core.indexing.ClipImageInput;import os.aios.core.indexing.FaceDecoder;import com.google.ai.edge.litert.*;
/** Test-only GPU retrieval benchmark using the production preprocessing and backend. */
public final class SearchBenchmark extends Instrumentation {
 private Bundle args;public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 public void onStart(){JSONObject report=new JSONObject();File root=new File(getTargetContext().getFilesDir(),"search-models"),fixtures=new File(getTargetContext().getFilesDir(),"fixtures");try{
  File[] photos=fixtures.listFiles((d,n)->n.endsWith(".jpg"));Arrays.sort(photos);JSONArray samples=new JSONArray();ArrayList<float[]> vectors=new ArrayList<>();
  long start=System.nanoTime();try(LiteRtGpuBackend image=new LiteRtGpuBackend(getTargetContext(),new File(root,"image.tflite").getPath())){report.put("image_load_ms",(System.nanoTime()-start)/1e6);double[] ms=new double[photos.length];
   for(int i=0;i<photos.length;i++){Bitmap b=BitmapFactory.decodeFile(photos[i].getPath());float[] in=ClipImageInput.encode(b);b.recycle();start=System.nanoTime();float[] v=image.run(in,null)[0];ms[i]=(System.nanoTime()-start)/1e6;vectors.add(v);samples.put(photos[i].getName());}report.put("image_warm",stats(ms));
   if(args!=null&&args.getString("sustain","false").equals("true")){float[] input=ClipImageInput.encode(BitmapFactory.decodeFile(photos[0].getPath()));long begun=SystemClock.elapsedRealtime(),next=begun;int count=0;JSONArray telemetry=new JSONArray();BatteryManager battery=getTargetContext().getSystemService(BatteryManager.class);PowerManager power=getTargetContext().getSystemService(PowerManager.class);while(SystemClock.elapsedRealtime()-begun<600000){image.run(input,null);count++;if(SystemClock.elapsedRealtime()>=next){JSONObject row=new JSONObject().put("elapsed_ms",SystemClock.elapsedRealtime()-begun).put("images",count).put("charge_counter_uah",battery.getIntProperty(BatteryManager.BATTERY_PROPERTY_CHARGE_COUNTER)).put("thermal",power.getCurrentThermalStatus());telemetry.put(row);next+=30000;Files.writeString(new File(root,"sustain-progress.json").toPath(),telemetry.toString());}if(count==1000)report.put("first_1000_ms",SystemClock.elapsedRealtime()-begun);}report.put("sustained_images",count).put("sustained_ms",SystemClock.elapsedRealtime()-begun).put("telemetry",telemetry);}
  }
  ByteBuffer buffer=ByteBuffer.allocate(vectors.size()*512*4).order(ByteOrder.LITTLE_ENDIAN);for(float[] v:vectors)for(float f:v)buffer.putFloat(f);Files.write(new File(root,"fixture-gpu-vectors.bin").toPath(),buffer.array());report.put("images",samples);
  JSONArray queries=new JSONArray(Files.readString(new File(root,"benchmark-queries.json").toPath())),ranks=new JSONArray();try(LiteRtGpuBackend text=new LiteRtGpuBackend(getTargetContext(),new File(root,"text.tflite").getPath())){for(int k=0;k<queries.length();k++){JSONObject q=queries.getJSONObject(k);JSONArray ts=q.getJSONArray("tokens");int[] tokens=new int[77];for(int i=0;i<77;i++)tokens[i]=ts.getInt(i);start=System.nanoTime();float[] v=text.run(null,tokens)[0];double time=(System.nanoTime()-start)/1e6;ArrayList<Integer> ids=new ArrayList<>();for(int i=0;i<vectors.size();i++)ids.add(i);ids.sort((a,b)->Double.compare(dot(v,vectors.get(b)),dot(v,vectors.get(a))));JSONArray order=new JSONArray();for(int id:ids)order.put(photos[id].getName());ranks.put(new JSONObject().put("query",q.getString("query")).put("ms",time).put("rank",order));}}report.put("queries",ranks);
  report.put("state","passed");
 }catch(Throwable e){try{report.put("state","failed").put("error",android.util.Log.getStackTraceString(e));}catch(Exception ignored){}}
 try{Files.writeString(new File(root,"benchmark.json").toPath(),report.toString(2));Bundle result=new Bundle();result.putString("report",report.toString());finish(report.optString("state").equals("passed")?-1:1,result);}catch(Exception e){finish(1,new Bundle());}}
 private static double dot(float[] a,float[] b){double d=0;for(int i=0;i<a.length;i++)d+=a[i]*b[i];return d;}
 private static JSONObject stats(double[] times)throws Exception{Arrays.sort(times);return new JSONObject().put("n",times.length).put("p50_ms",times[times.length/2]).put("p95_ms",times[Math.min(times.length-1,(int)(times.length*.95))]);}
}
